sys_ui_action.script:
//client function that runs "onclick"
function uHoCAddMemsApprovalClient() {
    if (confirm(getMessage("sn_hr_core.confirm.add.mems.approval"))) {
        //gsftSubmit(null, g_form.getFormElement(), "u_hoc_add_mems_approval");  //MUST be the "Action name" for this UI Action

        //call an Ajax function to insert a new Approval record and then open a new tab/window for the user to approve/reject the request
        var ga = new GlideAjax("global.HoCGlobalAjaxUtils");
        ga.addParam("sysparm_name", "manuallyOverrideApproval");
        ga.addParam("sysparm_id", g_form.getUniqueValue());  //the sys_id of the Case to approve
        ga.addParam("sysparm_table_name", g_form.getTableName());
        ga.getXMLAnswer(uHoCOpenPortal); //just returns the value of the answer node (much simpler and cleaner)
    }

    //callback function to process the response returned from the server
    function uHoCOpenPortal(response) {
        var result = JSON.parse(response); //transform the JSON string to an object
        if (result.approvalId != "" ) {
			//open the services portal in a new tab/window
			var url = new GlideURL("services");
			url.addParam("id", "hoc_hrm_todos_page");
			g_navigation.open(url.getURL(), "_blank");
		}
    }
}
